FROM authors
LEFT JOIN posts ON posts.author_id = authors.id;

examples.code:
CREATE TABLE products (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    name TEXT NOT NULL,
    price NUMERIC(10, 2) NOT NULL CHECK (price >= 0),
    sku TEXT NOT NULL UNIQUE
);

INSERT INTO products (name, price, sku) VALUES ('Keyboard', 49.99, 'KB-001');  -- OK

INSERT INTO products (name, price, sku) VALUES ('Broken Mouse', -5.00, 'MS-002');
-- ERROR:  new row for relation "products" violates check constraint "products_price_check"
-- DETAIL:  Failing row contains (2, Broken Mouse, -5.00, MS-002).

INSERT INTO products (name, price, sku) VALUES ('Keyboard Pro', 89.99, 'KB-001');
-- ERROR:  duplicate key value violates unique constraint "products_sku_key"
-- DETAIL:  Key (sku)=(KB-001) already exists.

-- people: (1, age=25), (2, age=NULL), (3, age=35)

SELECT * FROM people WHERE age = NULL;
-- returns ZERO rows -- even row 2, whose age genuinely IS NULL

SELECT * FROM people WHERE age IS NULL;
-- returns exactly row 2

-- banned_emails: ('spam@example.com'), (NULL)  -- a bad row snuck in
-- users: (1, 'amara@example.com'), (2, 'spam@example.com')

SELECT * FROM users WHERE email NOT IN (SELECT email FROM banned_emails);
-- returns ZERO rows -- even amara@example.com, which is clearly not banned!

SELECT * FROM users u
WHERE NOT EXISTS (
    SELECT 1 FROM banned_emails b WHERE b.email = u.email
);
-- returns exactly Amara's row, as intended

